-- « Statistiques cour d'appel » (LecteurStatistiquesCourAppel) : les colonnes qu'il lit, aux types de RIG_DEV (lu le
-- 26/11/2026), et des affaires de MARS 1971, une periode qu'aucun autre jeu ne touche : PROC_STATCA.recherches y calcule le
-- tableau, cellule par cellule. Les quatre lignes de la periode par defaut (PROC_STATCA.attendu) comptent aussi les instances
-- des autres jeux : elles n'y sont comparees que par leur categorie et leur periode, jamais par leurs chiffres.
-- Pas de procedure collective ici : PROC_MPC lit toutes celles de la base (decision du lot 3) ; les quatre compteurs du haut
-- de l'ecran sont controles contre RIG v2 sur RIG_DEV (statca_v2.sortie.txt / statca_v3.sortie.txt du compte rendu du lot 9).
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL, DCJDC_NUM_ORDRE smallint NOT NULL);
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE_PREVUE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE_PREVUE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_AVANT_DIRE_DROIT') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_AVANT_DIRE_DROIT varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DECISION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DECISION varchar(10) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_DELIBERER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_DELIBERER int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_PRONONCER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_PRONONCER int NULL;
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_LIBELLE_ECRAN varchar(100) NOT NULL);
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_SURSIS_STATUER') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_SURSIS_STATUER bit NULL;
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_ADD_EXPERTISE') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_ADD_EXPERTISE bit NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_CODE_PLUMITIF') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_CODE_PLUMITIF varchar(16) NULL;
-- Les colonnes des quatre compteurs (OPE_GENERER.cs:146-174), sur PROCEDURE_COLLECTIVE que d'autres jeux creent.
IF OBJECT_ID(N'v2.PROCEDURE_COLLECTIVE') IS NULL
    CREATE TABLE v2.PROCEDURE_COLLECTIVE (PRCLL_ID_PRCLL int NOT NULL PRIMARY KEY);
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_EXTERIEUR') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_EXTERIEUR bit NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_CODE_SOLUTION') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_CODE_SOLUTION varchar(5) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_CODE_SOLUTION_2') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_CODE_SOLUTION_2 varchar(5) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_CODE_CLOTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_CODE_CLOTURE varchar(5) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SOLUTION') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SOLUTION datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SOLUTION_2') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SOLUTION_2 datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_CLOTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_CLOTURE datetime NULL;

-- Les types de decision du banc : une decision « terminante » (ni sursis a statuer, ni expertise, ni avant-dire-droit,
-- OPE_GENERER.cs:187), un sursis a statuer (un jugement ADD, :375-432).
EXEC sp_executesql N'
INSERT INTO v2.TYPE_DECISION (R_TYPEDECISI_VALEUR, R_TYPEDECISI_LIBELLE_ECRAN, R_TYPEDECISI_SURSIS_STATUER, R_TYPEDECISI_ADD_EXPERTISE) VALUES
    (''B9TERM'', ''Jugement du banc 9'', 0, 0), (''B9SURS'', ''Sursis du banc 9'', 1, 0);';

-- Mars 1971 (01/03 au 31/03). Contentieux general (role J) :
--   J01 enrolee avant le debut, sans decision : EN COURS (B) ; jumeau refuse J02, enrolee avant, terminee le 15/02 (avant le debut).
--   J03 enrolee le 05/03 : NOUVELLE (C), terminee le 20/03 : TERMINEE (D), deliberee le 10/01 et prononcee le 20/03, deux mois
--       complets : DELIBERE DE PLUS DE DEUX MOIS (G). Jumeau refuse de C : J04, enrolee le 01/04 (apres la fin).
--   J05 enrolee avant, un sursis a statuer prevu le 10/03 : JUGEMENT ADD (E), et toujours en cours au debut (B).
--   J06 enrolee avant, appelee au plumitif « dX » sans decision : A DELIVRER (H), et en cours (B) ; jumeau refuse J07, plumitif
--       « di » (exclu, :528-577), en cours (B).
--   J08 enrolee avant, terminee le 25/03 (D), deliberee le 01/02 et prononcee le 25/03 : un seul mois complet, jumeau refuse de G ;
--       en cours au debut (B : sa decision suit le debut).
--   => B 5 (J01 J05 J06 J07 J08), C 1, D 2 (J03 J08), E 1, F = 5 + 1 - (2 + 1) = 3, G 1, H 1.
-- Procedure collective (role F) : F01 enrolee le 02/03 (C 1), plumitif « dp » sans decision (H 1) ; F = 1.
-- Referes (role R) : R01 enrolee le 20/01, sans decision (B 1), plumitif « df » (H 1) ; F = 1.
-- Injonctions de payer (role IP) : P01 enrolee le 03/03 (C 1), plumitif « d1 » sans decision : G et H valent 0 pour les IP
--   (:457-577, jumeau de H : J06) ; F = 1.
EXEC sp_executesql N'
