    (1909105, ''1971J190905'', ''STATCA J05'', ''19710201''), (1909106, ''1971J190906'', ''STATCA J06'', ''19710202''),
    (1909107, ''1971J190907'', ''STATCA J07'', ''19710203''), (1909108, ''1971J190908'', ''STATCA J08'', ''19710204''),
    (1909111, ''1971F190911'', ''STATCA F01'', ''19710302''), (1909121, ''1971R190921'', ''STATCA R01'', ''19710120''),
    (1909131, ''1971IP19093'', ''STATCA P01'', ''19710303'');
